-- Ya aplicado en Neon (proyecto Silver No Conformidades). Idempotente.
create table if not exists aud_procesos (codigo text primary key, nombre text not null, auditor_tipo text not null check (auditor_tipo in ('interno','externo')), orden int not null);
create table if not exists aud_checklist (id serial primary key, anio int not null, proceso text not null references aud_procesos(codigo), orden int not null, pregunta text not null, clausula text, guia text, unique (anio, proceso, orden));
create table if not exists aud_auditorias (id serial primary key, anio int not null, nro int not null, proceso text not null references aud_procesos(codigo), auditor text not null, funcion text, alcance text, temas text, criterios text, fecha_pedido text, fecha_programada text, fecha_auditoria date, hora_inicio text, resumen text, fecha_informe date, estado text not null default 'en_curso' check (estado in ('programada','en_curso','emitida')), origen text not null default 'app', creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now(), unique (anio, nro));
create table if not exists aud_resultados (auditoria_id int not null references aud_auditorias(id) on delete cascade, item_orden int not null, resultado text check (resultado in ('C','OM','HA','NC','NA')), evidencia text, redaccion text, actualizado_en timestamptz not null default now(), actualizado_por text, primary key (auditoria_id, item_orden));
create table if not exists aud_hallazgos (id serial primary key, auditoria_id int not null references aud_auditorias(id) on delete cascade, orden int not null, tipo text not null check (tipo in ('NC','HA','OM')), texto text not null, estado text not null default 'abierto' check (estado in ('abierto','cerrado','no_eficaz')), nc_numero int, creado_en timestamptz not null default now(), unique (auditoria_id, orden));
create table if not exists aud_seguimiento (auditoria_id int not null references aud_auditorias(id) on delete cascade, hallazgo_id int not null references aud_hallazgos(id), estado text check (estado in ('cerrado','abierto','no_eficaz')), evidencia text, actualizado_en timestamptz not null default now(), primary key (auditoria_id, hallazgo_id));
